-- 125: Original BrillaPrep WASSCE Islamic Religious Studies syllabus evidence beta questions, part 2.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_011', 'topic_was_irs_3', 'subj_wassce_irs', 'exam_wassce', 'What does Hijrah refer to in the Prophet’s life?', 'multiple_choice', '["A. The first revelation at Hira","B. The rebuilding of the Ka’bah before prophethood","C. The migration from Makkah to Madinah","D. The farewell sermon at Arafah"]', 'C', 'The Hijrah established a secure Muslim community in Madinah and marks the starting point used for the Islamic lunar calendar. Therefore the correct answer is C: The migration from Makkah to Madinah.', 'medium', 1, 1, 90, 'st_was_irs_3', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_012', 'topic_was_irs_3', 'subj_wassce_irs', 'exam_wassce', 'What was a key lesson of the brotherhood formed between the Muhajirun and Ansar?', 'multiple_choice', '["A. Tribal status must determine all rights","B. Migrants should remain permanently isolated","C. Wealth should never be shared","D. Community solidarity can overcome displacement and social division"]', 'D', 'The pairing supported displaced Makkan Muslims and strengthened mutual responsibility in the new Madinan community. Therefore the correct answer is D: Community solidarity can overcome displacement and social division.', 'hard', 2, 2, 90, 'st_was_irs_3', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_013', 'topic_was_irs_3', 'subj_wassce_irs', 'exam_wassce', 'Why was the Treaty of Hudaybiyyah strategically important?', 'multiple_choice', '["A. A period of peace created wider opportunities for contact and peaceful propagation","B. It ended every later disagreement immediately","C. It required Muslims to abandon Madinah","D. It prohibited all future pilgrimage"]', 'A', 'Although some terms initially seemed difficult, the truce reduced conflict and allowed communication that contributed to rapid community growth. Therefore the correct answer is A: A period of peace created wider opportunities for contact and peaceful propagation.', 'easy', 1, 1, 90, 'st_was_irs_3', 'Explain', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_014', 'topic_was_irs_3', 'subj_wassce_irs', 'exam_wassce', 'What happened during the first revelation?', 'multiple_choice', '["A. The Prophet was crowned king of Makkah","B. The angel Jibril commanded the Prophet to read or recite","C. The Qur’an was printed as a complete book","D. The Ka’bah was moved to Madinah"]', 'B', 'Islamic tradition records that the first verses of Surah al-Alaq were revealed through Jibril while the Prophet was in the cave of Hira. Therefore the correct answer is B: The angel Jibril commanded the Prophet to read or recite.', 'medium', 2, 2, 90, 'st_was_irs_3', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_015', 'topic_was_irs_3', 'subj_wassce_irs', 'exam_wassce', 'Which quality did the title al-Amin recognise in Muhammad before prophethood?', 'multiple_choice', '["A. Military rank","B. Ownership of every caravan","C. Trustworthiness","D. Authority as a Roman governor"]', 'C', 'People in Makkah recognised Muhammad as trustworthy and dependable, a character quality central to his later mission and leadership. Therefore the correct answer is C: Trustworthiness.', 'hard', 3, 3, 90, 'st_was_irs_3', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_016', 'topic_was_irs_4', 'subj_wassce_irs', 'exam_wassce', 'What does tawhid mean in Islamic belief?', 'multiple_choice', '["A. Worship of several independent deities","B. Rejection of all prophets","C. A method of commercial accounting","D. Belief in the absolute oneness of Allah"]', 'D', 'Tawhid is the foundation of Islamic belief: Allah alone is the creator and deserves worship without partners or rivals. Therefore the correct answer is D: Belief in the absolute oneness of Allah.', 'easy', 2, 2, 90, 'st_was_irs_4', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_017', 'topic_was_irs_4', 'subj_wassce_irs', 'exam_wassce', 'Which is one of the Five Pillars of Islam?', 'multiple_choice', '["A. Zakah","B. Tribal superiority","C. Monastic isolation","D. Fortune telling"]', 'A', 'Zakah is obligatory almsgiving on qualifying wealth and links worship with purification of wealth and responsibility toward eligible recipients. Therefore the correct answer is A: Zakah.', 'medium', 1, 1, 90, 'st_was_irs_4', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_018', 'topic_was_irs_4', 'subj_wassce_irs', 'exam_wassce', 'What is the primary declaration contained in the Shahadah?', 'multiple_choice', '["A. Every nation must use one language","B. There is no deity worthy of worship except Allah and Muhammad is His messenger","C. Wealth determines spiritual rank","D. Only scholars are accountable for conduct"]', 'B', 'The testimony expresses monotheism and acceptance of Muhammad’s prophethood, forming the verbal foundation of Muslim commitment. Therefore the correct answer is B: There is no deity worthy of worship except Allah and Muhammad is His messenger.', 'hard', 2, 2, 90, 'st_was_irs_4', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_019', 'topic_was_irs_4', 'subj_wassce_irs', 'exam_wassce', 'What does belief in qadar affirm?', 'multiple_choice', '["A. Human beings have no moral accountability","B. Planning for the future is forbidden","C. Allah’s knowledge and decree while humans remain responsible for chosen actions","D. Natural causes never operate"]', 'C', 'Belief in divine decree encourages trust in Allah without cancelling effort, choice, planning or accountability for deliberate conduct. Therefore the correct answer is C: Allah’s knowledge and decree while humans remain responsible for chosen actions.', 'easy', 1, 1, 90, 'st_was_irs_4', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_irs_b001_020', 'topic_was_irs_4', 'subj_wassce_irs', 'exam_wassce', 'Who are the messengers in Islamic belief?', 'multiple_choice', '["A. Angels who became human permanently","B. Rulers selected only by wealth","C. Authors of every historical book","D. Human beings chosen by Allah to convey guidance"]', 'D', 'Muslims believe Allah selected messengers from humanity, gave them revelation and made them models of faithful conduct. Therefore the correct answer is D: Human beings chosen by Allah to convey guidance.', 'medium', 3, 3, 90, 'st_was_irs_4', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.', 'https://www.waeconline.org.ng/e-learning/Islamic/IRKmain.html', 0, 1 FROM questions WHERE id BETWEEN 'q_was_irs_b001_011' AND 'q_was_irs_b001_020';
